services:
  postgres:
    image: postgres:17
    # pg_stat_statements attributes database load to statements. The module is
    # preloaded here; the extension itself is installed best effort whenever the
    # session store is migrated (channel ensure-db, db upgrade, backend startup).
    # max_connections: every captured run holds one writer connection and the
    # channel backend plus its gateway hold about twenty; 100 concurrent runs
    # must fit with headroom. Postgres defaults to 100.
    command:
      [
        "postgres",
        "-c",
        "shared_preload_libraries=pg_stat_statements",
        "-c",
        "max_connections=300",
      ]
    environment:
      POSTGRES_USER: tm
      POSTGRES_PASSWORD: tm
      POSTGRES_DB: transport_matters
    ports:
      - "127.0.0.1:${TRANSPORT_MATTERS_DOCKER_PG_PORT:-55432}:5432"
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U tm -d transport_matters"]
      interval: 2s
      timeout: 5s
      retries: 20
    volumes:
      - tm-postgres:/var/lib/postgresql/data

